<Variable name="wallpaperOpacity" description="Wallpaper opacity 0 to 1" type="string" default="0.18" value="0.18"/>
<Variable name="bannerImage" description="Homepage banner image URL blank none" type="string" default="" value=""/>
<Variable name="bannerHeight" description="Homepage banner height" type="string" default="220px" value="220px"/>
</Group>
<Group description="Homepage posts">
<Variable name="catCount" description="Random category panels on homepage 0 off" type="string" default="3" value="3"/>
<Variable name="catPosts" description="Posts per category panel 1 to 6" type="string" default="3" value="3"/>
<Variable name="catExclude" description="Labels to exclude comma separated" type="string" default="" value=""/>
