<Variable name="socialLinks" description="Social icons name X GitHub LinkedIn YouTube Facebook Instagram Telegram Website" type="string" default="X|https://x.com/;GitHub|https://github.com/;YouTube|https://www.youtube.com/" value="X|https://x.com/;GitHub|https://github.com/;YouTube|https://www.youtube.com/"/>
<Variable name="footerLinks" description="Footer links" type="string" default="Archive|/search;Privacy|/p/privacy.html;Terms|/p/terms.html;Contact|/p/contact.html" value="Archive|/search;Privacy|/p/privacy.html;Terms|/p/terms.html;Contact|/p/contact.html"/>
</Group>
