  $$('.cm-social a').forEach(function (a) {
    var k = a.textContent.trim().toLowerCase().replace(/[^a-z]/g, '');
    var p = ICONS[k] || ICONS.website;
    a.setAttribute('aria-label', a.textContent.trim());
